import{_ as r,C as i,o as d,c as n,j as o,a,E as t,a2 as h}from"./chunks/framework.BxGh02fV.js";const w=JSON.parse('{"title":"Take stock","description":"","frontmatter":{"title":"Take stock"},"headers":[],"relativePath":"en/agent/faire-le-point.md","filePath":"en/agent/faire-le-point.md"}'),l={name:"en/agent/faire-le-point.md"};function c(f,s,m,u,p,g){const e=i("Ask");return d(),n("div",null,[s[0]||(s[0]=o("h1",{id:"take-stock",tabindex:"-1"},[a("Take stock "),o("a",{class:"header-anchor",href:"#take-stock","aria-label":'Permalink to "Take stock"'},"​")],-1)),s[1]||(s[1]=o("p",null,"This journey helps you get your bearings: where the project stands, what awaits a decision from you, what happened in the last sessions. You come here at the start of a working session, or when you no longer know where you are.",-1)),s[2]||(s[2]=o("h2",{id:"what-you-ask-the-agent",tabindex:"-1"},[a("What you ask the agent "),o("a",{class:"header-anchor",href:"#what-you-ask-the-agent","aria-label":'Permalink to "What you ask the agent"'},"​")],-1)),t(e,{say:"Where does the project stand?",verb:"effortless_status",family:"pilotage"}),t(e,{say:"What is waiting for me?",verb:"effortless_attention",family:"pilotage"}),t(e,{say:"Show me the tree of epics and stories.",verb:"effortless_project_tree",family:"pilotage"}),t(e,{say:"What did we do in the last sessions?",verb:"effortless_sessions",family:"pilotage"}),t(e,{say:"Record this summary of the session: CSV export finished, tests to write.",verb:"effortless_session_summary",family:"pilotage",args:'{"summary":"CSV export finished, tests to write"}'}),t(e,{say:"Update my Kessho memory with the project's state.",verb:"effortless_secondbrain_sync",family:"pilotage"}),t(e,{say:"Which modules does the project declare, and what is their git state?",verb:"effortless_modules",family:"pilotage"}),t(e,{say:"Which work mode are we in? Switch to semi-auto.",verb:"effortless_mode_show",family:"pilotage"}),t(e,{say:"Which features does the agent have available?",verb:"effortless_features",family:"pilotage"}),s[3]||(s[3]=h('<h2 id="what-the-agent-does" tabindex="-1">What the agent does <a class="header-anchor" href="#what-the-agent-does" aria-label="Permalink to &quot;What the agent does&quot;">​</a></h2><h3 id="read-the-state" tabindex="-1">Read the state <a class="header-anchor" href="#read-the-state" aria-label="Permalink to &quot;Read the state&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/pilotage.html#status"><code>effortless_status</code></a> returns the full status: phases, active epic and story, backlog.</li><li><a href="/Effortless/en/reference/mcp/pilotage.html#attention"><code>effortless_attention</code></a> returns what awaits you: the work in progress, the open points (questions, recipes to verify, orphan tasks, critical anomalies, git, delivery, drift), the statistics and the queue. An unreadable source is named in <code>skipped</code>.</li><li><a href="/Effortless/en/reference/mcp/pilotage.html#project-tree"><code>effortless_project_tree</code></a> returns the whole tree: epics, stories, statuses.</li></ol><p>These three verbs read; they write nothing.</p><h3 id="see-the-modules" tabindex="-1">See the modules <a class="header-anchor" href="#see-the-modules" aria-label="Permalink to &quot;See the modules&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/pilotage.html#modules"><code>effortless_modules</code></a> lists the declared modules: identity (path, languages, model, standards), git state and version, delivery, and the work cited by the commits of their path over 90 days. <a href="/Effortless/en/reference/mcp/pilotage.html#widget-list"><code>effortless_widget_list</code></a> lists the dashboard&#39;s custom widgets. Both are read-only.</p><h3 id="pick-up-the-sessions" tabindex="-1">Pick up the sessions <a class="header-anchor" href="#pick-up-the-sessions" aria-label="Permalink to &quot;Pick up the sessions&quot;">​</a></h3><ol><li><a href="/Effortless/en/reference/mcp/pilotage.html#sessions"><code>effortless_sessions</code></a> returns the history, most recent first: the Kessho memory first, otherwise the local sessions of the machine. <code>last</code> gives the latest (title, summary); the reason for a fallback is in <code>skipped</code>.</li><li><a href="/Effortless/en/reference/mcp/pilotage.html#session-summary"><code>effortless_session_summary</code></a> writes the summary of the current session into <code>.effortless/sessions/</code>, local to your machine. Parameter: <code>summary</code>.</li><li><a href="/Effortless/en/reference/mcp/pilotage.html#secondbrain-sync"><code>effortless_secondbrain_sync</code></a> archives the project&#39;s state (OPALE phase, decisions and tasks of the active story) into your Kessho memory, through Kessho&#39;s own server: Effortless never writes into the vault. It writes an archive only if the state changed since the last one; otherwise it answers &quot;up to date&quot;. The Kessho project is found by its repository. If it does not exist, the <code>kessho:projetAbsent</code> refusal says so: with your consent, the agent calls the verb again with <code>create: true</code>, which creates it. The context you keep in Kessho is never modified.</li><li>Every closed story and epic is also archived in Kessho on its own. Without Kessho, closing still works: its answer says why nothing was archived.</li></ol><h3 id="set-the-mode" tabindex="-1">Set the mode <a class="header-anchor" href="#set-the-mode" aria-label="Permalink to &quot;Set the mode&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/pilotage.html#mode-show"><code>effortless_mode_show</code></a> gives the current mode with its description. <a href="/Effortless/en/reference/mcp/pilotage.html#mode-set"><code>effortless_mode_set</code></a> changes it (<code>full</code>, <code>semi-auto</code> or <code>tutore</code>) and writes it to <code>effortless.json</code>. What each mode allows: see <a href="./">With an agent</a>.</p><h3 id="list-what-effortless-can-do" tabindex="-1">List what Effortless can do <a class="header-anchor" href="#list-what-effortless-can-do" aria-label="Permalink to &quot;List what Effortless can do&quot;">​</a></h3><p><a href="/Effortless/en/reference/mcp/pilotage.html#features"><code>effortless_features</code></a> lists the verb registry. With <code>write_doc: true</code>, it regenerates <code>docs/FEATURES.md</code> and refreshes the derived section of <code>AGENTS.md</code> and the import in <code>CLAUDE.md</code>. Without that parameter, nothing is written.</p><h2 id="what-you-get" tabindex="-1">What you get <a class="header-anchor" href="#what-you-get" aria-label="Permalink to &quot;What you get&quot;">​</a></h2><ul><li>An answer from the agent that names the active epic and story, what is waiting, and the next useful step.</li><li>A session file in <code>.effortless/sessions/</code> after <code>effortless_session_summary</code>.</li><li>An updated work mode in <code>effortless.json</code>.</li><li>On screen: the <a href="/Effortless/en/guide/dashboard.html">Dashboard</a> is the resume screen (in progress, open points, git, statistics); the <a href="/Effortless/en/guide/backlog.html">Backlog</a> shows the tree and the session history; the <a href="/Effortless/en/guide/modules.html">Modules</a> screen shows the modules; the mode is set in <a href="/Effortless/en/guide/settings.html">Project settings</a>.</li></ul><h2 id="when-the-agent-is-refused" tabindex="-1">When the agent is refused <a class="header-anchor" href="#when-the-agent-is-refused" aria-label="Permalink to &quot;When the agent is refused&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Situation</th><th>What the refusal says</th><th>What to do</th></tr></thead><tbody><tr><td>A project verb is called outside a project</td><td><code>mcp:racineProjetIntrouvable</code></td><td>Set <code>EFFORTLESS_PROJECT</code> if the project exists elsewhere; otherwise <code>effortless_init</code> creates one.</td></tr><tr><td><code>effortless_session_summary</code> with an empty summary</td><td><code>sessions:summaryEmpty</code></td><td>Pass <code>summary</code>: what the session did and observed, in a few sentences.</td></tr><tr><td><code>effortless_mode_set</code> with an unknown mode</td><td>&quot;Invalid mode&quot; message, no code; nothing is written</td><td>Pass <code>full</code>, <code>semi-auto</code> or <code>tutore</code>.</td></tr><tr><td><code>effortless_features</code> with <code>write_doc: true</code> on a file that is not writable</td><td><code>guide:writeFailed</code></td><td>Make the named file writable, then call again with <code>write_doc: true</code>.</td></tr></tbody></table><p><code>effortless_status</code> and <code>effortless_features</code> also work before any project exists.</p>',17))])}const _=r(l,[["render",c]]);export{w as __pageData,_ as default};
